#!/usr/bin/env python3
"""Generate Active Satellites Analysis Report"""

import pandas as pd
import matplotlib.pyplot as plt
import matplotlib.patches as mpatches
import numpy as np
from datetime import datetime
import base64
from io import BytesIO
import re

# Load data
df = pd.read_csv('/app/benchmark/data.csv')
print(f"Loaded {len(df)} satellites")

# Convert ECCENTRICITY to float (has leading decimal point)
df['ECCENTRICITY'] = df['ECCENTRICITY'].apply(lambda x: float('0' + str(x)) if str(x).startswith('.') else float(x))

# Extract launch year from OBJECT_ID (format: YYYY-NNNXXX)
df['LAUNCH_YEAR'] = df['OBJECT_ID'].str[:4].astype(int)

# Classify orbital regimes using MEAN_MOTION thresholds
# LEO: >14 rev/day, GEO: ~1.0 rev/day, MEO: between, HEO: highly eccentric or unusual
def classify_orbit(row):
    mm = row['MEAN_MOTION']
    ecc = row['ECCENTRICITY']
    # HEO: highly eccentric orbits (Molniya etc.) or mean motion outside normal ranges
    if ecc > 0.3 or (mm < 2 and mm > 0.5):
        return 'HEO'
    elif mm > 14:
        return 'LEO'
    elif mm >= 0.9 and mm <= 1.1:
        return 'GEO'
    elif mm > 1 and mm <= 14:
        return 'MEO'
    else:
        return 'OTHER'

df['ORBIT_REGIME'] = df.apply(classify_orbit, axis=1)

# Identify constellation/operator from OBJECT_NAME
def identify_constellation(name):
    name_upper = str(name).upper()
    if name_upper.startswith('STARLINK'):
        return 'Starlink'
    elif name_upper.startswith('ONEWEB'):
        return 'OneWeb'
    elif name_upper.startswith('IRIDIUM'):
        return 'Iridium'
    elif name_upper.startswith('GLOBALSTAR'):
        return 'Globalstar'
    elif name_upper.startswith('ORBCOMM'):
        return 'Orbcomm'
    elif name_upper.startswith('GPS'):
        return 'GPS'
    elif name_upper.startswith('GALILEO'):
        return 'Galileo'
    elif name_upper.startswith('BEIDOU'):
        return 'BeiDou'
    elif name_upper.startswith('GLONASS'):
        return 'GLONASS'
    elif name_upper.startswith('SES'):
        return 'SES'
    elif name_upper.startswith('INTELSAT'):
        return 'Intelsat'
    elif name_upper.startswith('HAS'):
        return 'Hawana'
    elif name_upper.startswith('AMAZON'):
        return 'Amazon Kuiper'
    elif name_upper.startswith('AMAZONIA'):
        return 'Amazon (Other)'
    elif 'PLANET' in name_upper or name_upper.startswith('FLOCK'):
        return 'Planet (Dove)'
    elif name_upper.startswith('SKYSAT'):
        return 'Planet (SkySat)'
    elif name_upper.startswith('RAPIDEYE'):
        return 'RapidEye'
    elif name_upper.startswith('AURORA'):
        return 'Aurora'
    elif 'CUBESAT' in name_upper or name_upper.startswith('CNC'):
        return 'CubeSats'
    elif 'ISS' in name_upper or name_upper.startswith('ZARYA'):
        return 'ISS'
    elif name_upper.startswith('COSMOS') or name_upper.startswith('СОЮЗ'):
        return 'Cosmos'
    elif name_upper.startswith('TIANGONG'):
        return 'Tiangong'
    elif name_upper.startswith('SHENZHOU'):
        return 'Shenzhou'
    else:
        return 'Other'

df['CONSTELLATION'] = df['OBJECT_NAME'].apply(identify_constellation)

# Calculate KPIs
total_satellites = len(df)
leo_count = len(df[df['ORBIT_REGIME'] == 'LEO'])
leo_share = (leo_count / total_satellites) * 100
starlink_count = len(df[df['CONSTELLATION'] == 'Starlink'])
median_inclination = df['INCLINATION'].median()
post_2020_count = len(df[df['LAUNCH_YEAR'] >= 2020])

# Print KPIs
print(f"\n=== KPIs ===")
print(f"Total Active Satellites: {total_satellites:,}")
print(f"LEO Share: {leo_share:.1f}%")
print(f"Starlink Constellation Size: {starlink_count:,}")
print(f"Median Inclination: {median_inclination:.1f}°")
print(f"Post-2020 Launches: {post_2020_count:,}")

# Orbital regime distribution
regime_counts = df['ORBIT_REGIME'].value_counts()
print(f"\n=== Orbital Regime Distribution ===")
for regime, count in regime_counts.items():
    print(f"{regime}: {count:,} ({count/total_satellites*100:.1f}%)")

# Top 10 constellations
constellation_counts = df['CONSTELLATION'].value_counts()
print(f"\n=== Top 10 Constellations ===")
for const, count in constellation_counts.head(10).items():
    print(f"{const}: {count:,}")

# Launch year distribution
year_counts = df['LAUNCH_YEAR'].value_counts().sort_index()
print(f"\n=== Launch Years ===")
print(f"Year range: {df['LAUNCH_YEAR'].min()} - {df['LAUNCH_YEAR'].max()}")
print(f"Post-2020: {post_2020_count:,} satellites")

# Epoch range
print(f"\n=== Epoch Range ===")
print(f"Earliest: {df['EPOCH'].min()}")
print(f"Latest: {df['EPOCH'].max()}")

# ============================================
# CREATE VISUALIZATIONS
# ============================================

# Set style
plt.style.use('seaborn-v0_8-whitegrid')
plt.rcParams['font.family'] = 'DejaVu Sans'
plt.rcParams['figure.facecolor'] = 'white'

# Color palette
COLORS = {
    'primary': '#1a56db',
    'secondary': '#7e3af2',
    'accent': '#059669',
    'warning': '#dc2626',
    'gray': '#6b7280',
    'leo': '#059669',
    'meo': '#2563eb',
    'geo': '#7c3aed',
    'heo': '#dc2626',
    'other': '#6b7280'
}

# 1. Launch Trends - Most Important Chart
fig_launch, ax_launch = plt.subplots(figsize=(14, 7))
years = year_counts.sort_index()
recent_years = years[years.index >= 1990]

bars = ax_launch.bar(recent_years.index, recent_years.values, color=COLORS['primary'], alpha=0.85, edgecolor='white', linewidth=0.5)

# Highlight post-2020
post_2020_years = recent_years[recent_years.index >= 2020]
ax_launch.bar(post_2020_years.index, post_2020_years.values, color=COLORS['accent'], alpha=0.9, edgecolor='white', linewidth=0.5)

# Add annotations for key years
for year in [2020, 2021, 2022, 2023, 2024, 2025]:
    if year in recent_years.index:
        ax_launch.annotate(f'{recent_years[year]:,}', xy=(year, recent_years[year]),
                          ha='center', va='bottom', fontsize=8, fontweight='bold')

ax_launch.set_xlabel('Launch Year', fontsize=12, fontweight='bold')
ax_launch.set_ylabel('Number of Active Satellites', fontsize=12, fontweight='bold')
ax_launch.set_title('Launch Year Trends: Active Satellites by Launch Year\n(2020+ Highlighted in Green)', fontsize=14, fontweight='bold')
ax_launch.set_xlim(1989.5, 2026.5)

# Add cumulative overlay on secondary y-axis
ax_cumulative = ax_launch.twinx()
cumulative = recent_years.cumsum()
ax_cumulative.plot(cumulative.index, cumulative.values, color=COLORS['warning'], linewidth=2.5, linestyle='--', marker='o', markersize=4, label='Cumulative Total')
ax_cumulative.set_ylabel('Cumulative Satellites', fontsize=12, fontweight='bold', color=COLORS['warning'])
ax_cumulative.tick_params(axis='y', labelcolor=COLORS['warning'])

# Legend
legend_patches = [
    mpatches.Patch(color=COLORS['primary'], label='1990-2019 Launches'),
    mpatches.Patch(color=COLORS['accent'], label='2020+ Launches'),
    plt.Line2D([0], [0], color=COLORS['warning'], linestyle='--', marker='o', markersize=4, label='Cumulative Total')
]
ax_launch.legend(handles=legend_patches, loc='upper left', framealpha=0.9)

plt.tight_layout()
launch_chart_buffer = BytesIO()
plt.savefig(launch_chart_buffer, format='png', dpi=150, bbox_inches='tight', facecolor='white')
launch_chart_buffer.seek(0)
launch_chart_base64 = base64.b64encode(launch_chart_buffer.read()).decode()
plt.close()

# 2. Orbital Regime Pie Chart
fig_pie, ax_pie = plt.subplots(figsize=(10, 8))
regime_order = ['LEO', 'MEO', 'GEO', 'HEO', 'OTHER']
regime_colors = [COLORS['leo'], COLORS['meo'], COLORS['geo'], COLORS['heo'], COLORS['gray']]
regime_vals = [regime_counts.get(r, 0) for r in regime_order]
regime_labels = [f"{r}\n{regime_counts.get(r, 0):,} ({regime_counts.get(r, 0)/total_satellites*100:.1f}%)" for r in regime_order]

wedges, texts, autotexts = ax_pie.pie(regime_vals, labels=regime_labels, colors=regime_colors,
                                        autopct='', startangle=90, pctdistance=0.75,
                                        wedgeprops={'edgecolor': 'white', 'linewidth': 2})
for autotext in autotexts:
    autotext.set_fontsize(11)
    autotext.set_fontweight('bold')

ax_pie.set_title('Orbital Regime Distribution\n(Based on Mean Motion Thresholds)', fontsize=14, fontweight='bold')

# Add legend
legend_patches = [mpatches.Patch(color=regime_colors[i], label=f'{regime_order[i]}: {regime_vals[i]:,}') for i in range(len(regime_order))]
ax_pie.legend(handles=legend_patches, loc='lower center', bbox_to_anchor=(0.5, -0.1), ncol=5, framealpha=0.9)

plt.tight_layout()
pie_chart_buffer = BytesIO()
plt.savefig(pie_chart_buffer, format='png', dpi=150, bbox_inches='tight', facecolor='white')
pie_chart_buffer.seek(0)
pie_chart_base64 = base64.b64encode(pie_chart_buffer.read()).decode()
plt.close()

# 3. Constellation Breakdown - Bar Chart (Top 15)
fig_const, ax_const = plt.subplots(figsize=(12, 8))
top_const = constellation_counts.head(15)
colors_const = [COLORS['accent'] if c == 'Starlink' else COLORS['primary'] for c in top_const.index]

bars = ax_const.barh(range(len(top_const)), top_const.values, color=colors_const, edgecolor='white', linewidth=0.5)
ax_const.set_yticks(range(len(top_const)))
ax_const.set_yticklabels(top_const.index)
ax_const.invert_yaxis()
ax_const.set_xlabel('Number of Satellites', fontsize=12, fontweight='bold')
ax_const.set_title('Top 15 Satellite Constellations & Operators\n(Starlink Highlighted in Green)', fontsize=14, fontweight='bold')

# Add value labels
for i, (bar, val) in enumerate(zip(bars, top_const.values)):
    ax_const.text(val + 50, bar.get_y() + bar.get_height()/2, f'{val:,}', va='center', fontsize=9)

# Add Starlink annotation
starlink_pos = list(top_const.index).index('Starlink') if 'Starlink' in top_const.index else -1
if starlink_pos >= 0:
    ax_const.annotate(f'{starlink_count:,} satellites\n({starlink_count/total_satellites*100:.1f}% of total)',
                      xy=(starlink_count, starlink_pos), xytext=(starlink_count + 500, starlink_pos + 2),
                      fontsize=10, fontweight='bold', color=COLORS['accent'],
                      arrowprops=dict(arrowstyle='->', color=COLORS['accent']))

plt.tight_layout()
const_chart_buffer = BytesIO()
plt.savefig(const_chart_buffer, format='png', dpi=150, bbox_inches='tight', facecolor='white')
const_chart_buffer.seek(0)
const_chart_base64 = base64.b64encode(const_chart_buffer.read()).decode()
plt.close()

# 4. Inclination Distribution
fig_incl, ax_incl = plt.subplots(figsize=(12, 6))
ax_incl.hist(df['INCLINATION'], bins=50, color=COLORS['primary'], alpha=0.7, edgecolor='white', linewidth=0.5)
ax_incl.axvline(median_inclination, color=COLORS['warning'], linestyle='--', linewidth=2, label=f'Median: {median_inclination:.1f}°')
ax_incl.set_xlabel('Inclination (degrees)', fontsize=12, fontweight='bold')
ax_incl.set_ylabel('Number of Satellites', fontsize=12, fontweight='bold')
ax_incl.set_title('Inclination Distribution\n(Orbital Tilt Relative to Equator)', fontsize=14, fontweight='bold')
ax_incl.legend(fontsize=11)

# Add annotations for common inclinations
common_inclinations = [
    (53, 'Starlink Shell 1 (53°)', COLORS['accent']),
    (70, 'Polar/Sun-synch (~70°)', COLORS['secondary']),
    (90, 'Polar (90°)', COLORS['gray'])
]
for incl, label, color in common_inclinations:
    ax_incl.axvline(incl, color=color, linestyle=':', alpha=0.7)
    ax_incl.text(incl + 2, ax_incl.get_ylim()[1] * 0.9, label, rotation=90, fontsize=8, va='top', color=color)

plt.tight_layout()
incl_chart_buffer = BytesIO()
plt.savefig(incl_chart_buffer, format='png', dpi=150, bbox_inches='tight', facecolor='white')
incl_chart_buffer.seek(0)
incl_chart_base64 = base64.b64encode(incl_chart_buffer.read()).decode()
plt.close()

# 5. Mean Motion Distribution (Orbit Altitude Proxy)
fig_mm, ax_mm = plt.subplots(figsize=(12, 6))
leo_df = df[df['ORBIT_REGIME'] == 'LEO']
other_df = df[df['ORBIT_REGIME'] != 'LEO']

ax_mm.hist(other_df['MEAN_MOTION'], bins=50, color=COLORS['gray'], alpha=0.5, edgecolor='white', label='MEO/GEO/HEO/Other')
ax_mm.hist(leo_df['MEAN_MOTION'], bins=50, color=COLORS['leo'], alpha=0.7, edgecolor='white', label='LEO')

ax_mm.axvline(14, color=COLORS['warning'], linestyle='--', linewidth=2, label='LEO threshold (14 rev/day)')
ax_mm.set_xlabel('Mean Motion (revolutions per day)', fontsize=12, fontweight='bold')
ax_mm.set_ylabel('Number of Satellites', fontsize=12, fontweight='bold')
ax_mm.set_title('Mean Motion Distribution\n(Proxy for Orbital Altitude)', fontsize=14, fontweight='bold')
ax_mm.legend(fontsize=11)

plt.tight_layout()
mm_chart_buffer = BytesIO()
plt.savefig(mm_chart_buffer, format='png', dpi=150, bbox_inches='tight', facecolor='white')
mm_chart_buffer.seek(0)
mm_chart_base64 = base64.b64encode(mm_chart_buffer.read()).decode()
plt.close()

# 6. Eccentricity Distribution
fig_ecc, ax_ecc = plt.subplots(figsize=(12, 6))
# Focus on non-zero eccentricities for detail view
ecc_nonzero = df[df['ECCENTRICITY'] > 0.001]['ECCENTRICITY']
ax_ecc.hist(ecc_nonzero, bins=50, color=COLORS['secondary'], alpha=0.7, edgecolor='white', linewidth=0.5)
ax_ecc.axvline(ecc_nonzero.median(), color=COLORS['warning'], linestyle='--', linewidth=2, label=f'Median: {ecc_nonzero.median():.4f}')
ax_ecc.set_xlabel('Eccentricity', fontsize=12, fontweight='bold')
ax_ecc.set_ylabel('Number of Satellites', fontsize=12, fontweight='bold')
ax_ecc.set_title('Eccentricity Distribution\n(0 = Circular Orbit, →1 = Highly Elliptical)', fontsize=14, fontweight='bold')
ax_ecc.legend(fontsize=11)

# Highlight highly eccentric orbits (potential HEO)
high_ecc = df[df['ECCENTRICITY'] > 0.3]
if len(high_ecc) > 0:
    ax_ecc.annotate(f'Highly Elliptical Orbits (e>0.3):\n{len(high_ecc):,}',
                    xy=(0.6, ax_ecc.get_ylim()[1] * 0.8), fontsize=10, color=COLORS['warning'], fontweight='bold')

plt.tight_layout()
ecc_chart_buffer = BytesIO()
plt.savefig(ecc_chart_buffer, format='png', dpi=150, bbox_inches='tight', facecolor='white')
ecc_chart_buffer.seek(0)
ecc_chart_base64 = base64.b64encode(ecc_chart_buffer.read()).decode()
plt.close()

# 7. Starlink Inclination Breakdown
fig_starlink_inc, ax_starlink_inc = plt.subplots(figsize=(10, 6))
starlink_df = df[df['CONSTELLATION'] == 'Starlink']
starlink_incl = starlink_df['INCLINATION'].value_counts().sort_index()
ax_starlink_inc.bar(starlink_incl.index.astype(str), starlink_incl.values, color=COLORS['accent'], alpha=0.85, edgecolor='white')
ax_starlink_inc.set_xlabel('Inclination (degrees)', fontsize=12, fontweight='bold')
ax_starlink_inc.set_ylabel('Number of Starlink Satellites', fontsize=12, fontweight='bold')
ax_starlink_inc.set_title('Starlink Constellation: Inclination Distribution\nShell Structure Analysis', fontsize=14, fontweight='bold')

for inc, count in starlink_incl.items():
    ax_starlink_inc.annotate(f'{count:,}', xy=(str(inc), count), ha='center', va='bottom', fontsize=9, fontweight='bold')

plt.tight_layout()
starlink_inc_buffer = BytesIO()
plt.savefig(starlink_inc_buffer, format='png', dpi=150, bbox_inches='tight', facecolor='white')
starlink_inc_buffer.seek(0)
starlink_inc_base64 = base64.b64encode(starlink_inc_buffer.read()).decode()
plt.close()

# 8. Year-over-Year Growth Rate
fig_growth, ax_growth = plt.subplots(figsize=(12, 6))
growth_rate = recent_years.pct_change() * 100
colors_growth = [COLORS['accent'] if v > 0 else COLORS['warning'] for v in growth_rate.values]
ax_growth.bar(growth_rate.index, growth_rate.values, color=colors_growth, alpha=0.8, edgecolor='white')
ax_growth.axhline(0, color='black', linewidth=0.5)
ax_growth.set_xlabel('Year', fontsize=12, fontweight='bold')
ax_growth.set_ylabel('Year-over-Year Growth (%)', fontsize=12, fontweight='bold')
ax_growth.set_title('Annual Launch Rate Growth\n(Percentage Increase in Active Satellites)', fontsize=14, fontweight='bold')

# Add labels for significant years
for year in [2020, 2021, 2022, 2023, 2024]:
    if year in growth_rate.index and not pd.isna(growth_rate[year]):
        ax_growth.annotate(f'{growth_rate[year]:.0f}%', xy=(year, growth_rate[year]),
                          ha='center', va='bottom' if growth_rate[year] > 0 else 'top', fontsize=8, fontweight='bold')

