#!/usr/bin/env python3
"""Generate Active Satellites Analysis Report"""

import pandas as pd
import matplotlib.pyplot as plt
import matplotlib.patches as mpatches
import numpy as np
from datetime import datetime
import base64
from io import BytesIO
import re

# Load data
df = pd.read_csv('/app/benchmark/data.csv')
print(f"Loaded {len(df)} satellites")

# Convert ECCENTRICITY to float (has leading decimal point)
df['ECCENTRICITY'] = df['ECCENTRICITY'].apply(lambda x: float('0' + str(x)) if str(x).startswith('.') else float(x))

# Extract launch year from OBJECT_ID (format: YYYY-NNNXXX)
df['LAUNCH_YEAR'] = df['OBJECT_ID'].str[:4].astype(int)

# Classify orbital regimes using MEAN_MOTION thresholds
def classify_orbit(row):
    mm = row['MEAN_MOTION']
    ecc = row['ECCENTRICITY']
    if ecc > 0.3 or (mm < 2 and mm > 0.5):
        return 'HEO'
    elif mm > 14:
        return 'LEO'
    elif mm >= 0.9 and mm <= 1.1:
        return 'GEO'
    elif mm > 1 and mm <= 14:
        return 'MEO'
    else:
        return 'OTHER'

df['ORBIT_REGIME'] = df.apply(classify_orbit, axis=1)

# Identify constellation/operator from OBJECT_NAME
def identify_constellation(name):
    name_upper = str(name).upper()
    if name_upper.startswith('STARLINK'):
        return 'Starlink'
    elif name_upper.startswith('ONEWEB'):
        return 'OneWeb'
    elif name_upper.startswith('IRIDIUM'):
        return 'Iridium'
    elif name_upper.startswith('GLOBALSTAR'):
        return 'Globalstar'
    elif name_upper.startswith('ORBCOMM'):
        return 'Orbcomm'
    elif name_upper.startswith('GPS'):
        return 'GPS'
    elif name_upper.startswith('GALILEO'):
        return 'Galileo'
    elif name_upper.startswith('BEIDOU'):
        return 'BeiDou'
    elif name_upper.startswith('GLONASS'):
        return 'GLONASS'
    elif name_upper.startswith('SES'):
        return 'SES'
    elif name_upper.startswith('INTELSAT'):
        return 'Intelsat'
    elif name_upper.startswith('HAS'):
        return 'Hawana'
    elif name_upper.startswith('AMAZON'):
        return 'Amazon Kuiper'
    elif name_upper.startswith('AMAZONIA'):
        return 'Amazon (Other)'
    elif 'PLANET' in name_upper or name_upper.startswith('FLOCK'):
        return 'Planet (Dove)'
    elif name_upper.startswith('SKYSAT'):
        return 'Planet (SkySat)'
    elif name_upper.startswith('RAPIDEYE'):
        return 'RapidEye'
    elif name_upper.startswith('AURORA'):
        return 'Aurora'
    elif 'CUBESAT' in name_upper or name_upper.startswith('CNC'):
        return 'CubeSats'
    elif 'ISS' in name_upper or name_upper.startswith('ZARYA'):
        return 'ISS'
    elif name_upper.startswith('COSMOS') or name_upper.startswith('СОЮЗ'):
        return 'Cosmos'
    elif name_upper.startswith('TIANGONG'):
        return 'Tiangong'
    elif name_upper.startswith('SHENZHOU'):
        return 'Shenzhou'
    else:
        return 'Other'

df['CONSTELLATION'] = df['OBJECT_NAME'].apply(identify_constellation)

# Calculate KPIs
total_satellites = len(df)
leo_count = len(df[df['ORBIT_REGIME'] == 'LEO'])
leo_share = (leo_count / total_satellites) * 100
starlink_count = len(df[df['CONSTELLATION'] == 'Starlink'])
median_inclination = df['INCLINATION'].median()
post_2020_count = len(df[df['LAUNCH_YEAR'] >= 2020])

# Print KPIs
print(f"\n=== KPIs ===")
print(f"Total Active Satellites: {total_satellites:,}")
print(f"LEO Share: {leo_share:.1f}%")
print(f"Starlink Constellation Size: {starlink_count:,}")
print(f"Median Inclination: {median_inclination:.1f}°")
print(f"Post-2020 Launches: {post_2020_count:,}")

# Orbital regime distribution
regime_counts = df['ORBIT_REGIME'].value_counts()
print(f"\n=== Orbital Regime Distribution ===")
for regime, count in regime_counts.items():
    print(f"{regime}: {count:,} ({count/total_satellites*100:.1f}%)")

# Top 10 constellations
constellation_counts = df['CONSTELLATION'].value_counts()
print(f"\n=== Top 10 Constellations ===")
for const, count in constellation_counts.head(10).items():
    print(f"{const}: {count:,}")

# Launch year distribution
year_counts = df['LAUNCH_YEAR'].value_counts().sort_index()
print(f"\n=== Launch Years ===")
print(f"Year range: {df['LAUNCH_YEAR'].min()} - {df['LAUNCH_YEAR'].max()}")
print(f"Post-2020: {post_2020_count:,} satellites")

# ============================================
# CREATE VISUALIZATIONS
# ============================================

plt.style.use('seaborn-v0_8-whitegrid')
plt.rcParams['font.family'] = 'DejaVu Sans'
plt.rcParams['figure.facecolor'] = 'white'

COLORS = {
    'primary': '#1a56db',
    'secondary': '#7e3af2',
    'accent': '#059669',
    'warning': '#dc2626',
    'gray': '#6b7280',
    'leo': '#059669',
    'meo': '#2563eb',
    'geo': '#7c3aed',
    'heo': '#dc2626',
}

def save_chart(fig):
    """Save chart to base64 and close"""
    buffer = BytesIO()
    fig.savefig(buffer, format='png', dpi=150, bbox_inches='tight', facecolor='white')
    buffer.seek(0)
    b64 = base64.b64encode(buffer.read()).decode()
    plt.close(fig)
    return b64

# 1. Launch Trends
print("Creating chart 1: Launch Trends...")
fig_launch, ax_launch = plt.subplots(figsize=(14, 7))
years = year_counts.sort_index()
recent_years = years[years.index >= 1990]

ax_launch.bar(recent_years.index, recent_years.values, color=COLORS['primary'], alpha=0.85, edgecolor='white', linewidth=0.5)
post_2020_years = recent_years[recent_years.index >= 2020]
ax_launch.bar(post_2020_years.index, post_2020_years.values, color=COLORS['accent'], alpha=0.9, edgecolor='white', linewidth=0.5)

# Annotate key years
for year in [2020, 2021, 2022, 2023, 2024, 2025]:
    if year in recent_years.index:
        yval = recent_years[year]
        ax_launch.annotate(f'{yval:,}', xy=(year, yval), ha='center', va='bottom', fontsize=8, fontweight='bold')

ax_launch.set_xlabel('Launch Year', fontsize=12, fontweight='bold')
ax_launch.set_ylabel('Number of Active Satellites', fontsize=12, fontweight='bold')
ax_launch.set_title('Launch Year Trends: Active Satellites by Launch Year\n(2020+ Highlighted in Green)', fontsize=14, fontweight='bold')
ax_launch.set_xlim(1989.5, 2026.5)

# Cumulative overlay
ax_cumulative = ax_launch.twinx()
cumulative = recent_years.cumsum()
ax_cumulative.plot(cumulative.index, cumulative.values, color=COLORS['warning'], linewidth=2.5, linestyle='--', marker='o', markersize=4)
ax_cumulative.set_ylabel('Cumulative Satellites', fontsize=12, fontweight='bold', color=COLORS['warning'])
ax_cumulative.tick_params(axis='y', labelcolor=COLORS['warning'])

legend_patches = [
    mpatches.Patch(color=COLORS['primary'], label='1990-2019 Launches'),
    mpatches.Patch(color=COLORS['accent'], label='2020+ Launches'),
    plt.Line2D([0], [0], color=COLORS['warning'], linestyle='--', marker='o', markersize=4, label='Cumulative Total')
]
ax_launch.legend(handles=legend_patches, loc='upper left', framealpha=0.9)
