        .kpi-card.accent {{ border-left-color: var(--accent); background: linear-gradient(135deg, #ecfdf5 0%, #d1fae5 100%); }}
        .kpi-card.warning {{ border-left-color: var(--warning); }}
        .kpi-card.secondary {{ border-left-color: var(--secondary); }}

        .kpi-value {{ font-size: 2rem; font-weight: 700; color: var(--text-dark); line-height: 1.2; }}
        .kpi-label {{ font-size: 0.875rem; color: var(--text-muted); margin-top: 4px; }}

        .section h3 {{ font-size: 1.1rem; font-weight: 600; color: var(--text-dark); margin: 20px 0 12px 0; }}
        .section p {{ margin-bottom: 12px; color: var(--text-muted); }}

        .chart-container {{ margin: 20px 0; text-align: center; }}
        .chart-container img {{ max-width: 100%; height: auto; border-radius: 8px; box-shadow: 0 2px 8px rgba(0,0,0,0.1); }}
        .chart-caption {{ font-size: 0.85rem; color: var(--text-muted); margin-top: 8px; font-style: italic; }}

        table {{ width: 100%; border-collapse: collapse; margin: 16px 0; font-size: 0.9rem; }}
        th, td {{ padding: 12px; text-align: left; border-bottom: 1px solid var(--border); }}
        th {{ background: var(--bg-light); font-weight: 600; color: var(--text-dark); }}
        tr:hover {{ background: var(--bg-light); }}
        .number {{ text-align: right; font-variant-numeric: tabular-nums; }}
        .pct {{ text-align: right; color: var(--text-muted); }}

        .key-finding {{
            background: linear-gradient(135deg, #eff6ff 0%, #dbeafe 100%);
            border-left: 4px solid var(--primary);
            padding: 16px 20px;
            margin: 16px 0;
            border-radius: 0 8px 8px 0;
        }}

        .key-finding.accent {{ background: linear-gradient(135deg, #ecfdf5 0%, #d1fae5 100%); border-left-color: var(--accent); }}
        .key-finding.warning {{ background: linear-gradient(135deg, #fef2f2 0%, #fee2e2 100%); border-left-color: var(--warning); }}
        .key-finding strong {{ color: var(--text-dark); }}

        .two-col {{ display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }}
        @media (max-width: 768px) {{ .two-col {{ grid-template-columns: 1fr; }} }}

        .executive-summary {{
            background: linear-gradient(135deg, #1e3a5f 0%, #0f172a 100%);
            color: white;
            border-radius: 12px;
            padding: 30px;
            margin-bottom: 30px;
